# Functies in Python
def begroet(naam, leeftijd):
    return f"Hallo {naam}, je bent {leeftijd} jaar oud!"

def kwadraat(n):
    return n ** 2

# Aanroepen
print(begroet("Emma", 16))
print(begroet("Liam", 17))

for getal in range(1, 6):
    print(f"{getal}² = {kwadraat(getal)}")

# If/else in Python
score = int(input("Geef je score (0-100): "))

if score >= 90:
    resultaat = "A — Uitstekend!"
elif score >= 75:
    resultaat = "B — Goed!"
elif score >= 60:
    resultaat = "C — Voldoende"
elif score >= 50:
    resultaat = "D — Net geslaagd"
else:
    resultaat = "F — Niet geslaagd"

print(f"Score {score}: {resultaat}")

# Klassen in Python
class Dier:
    def __init__(self, naam, soort):
        self.naam = naam
        self.soort = soort

    def stel_voor(self):
        return f"Ik ben {self.naam}, een {self.soort}."

    def geluid(self):
        return "..."

class Hond(Dier):
    def geluid(self):
        return "Woef!"

class Kat(Dier):
    def geluid(self):
        return "Miauw!"

# Gebruik
hond = Hond("Rex", "hond")
kat = Kat("Mimi", "kat")

for dier in [hond, kat]:
    print(dier.stel_voor())
    print(f"Geluid: {dier.geluid()}")
    print()
